import { EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
export interface NavLink {
  label: string;
  url: string;
}

@Component({
  selector: 'lib-navbar',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './navbar.html',
  styleUrl: './navbar.css',
})
export class Navbar {
  @Input() brand = 'Aero';
  @Input() links: NavLink[] = [
    { label: 'Home', url: '/' },
    { label: 'About', url: '/about' },
    { label: 'Contact', url: '/contact' }
  ];
  @Input() initiallyLoggedIn = false;
  @Input() userName = 'Guest User';
  @Input() userEmail = 'guest@example.com';

  @Input() image = 'https://i.pinimg.com/1200x/4a/57/0c/4a570c4e8dbb4729567848eb69c19055.jpg';

  @Output() login = new EventEmitter();
  @Output() logout = new EventEmitter();

  isLoggedIn = false;
  isDropdownOpen = false;
 

  constructor(private elementRef: ElementRef) { }

  ngOnInit() {
    this.isLoggedIn = this.initiallyLoggedIn;
  }

  handleLoginClick() {
    this.isLoggedIn = true;
    this.login.emit();
  }

  handleProfileClick() {
    this.isDropdownOpen = !this.isDropdownOpen;
  }

  handleLogoutClick() {
    this.isLoggedIn = false;
    this.isDropdownOpen = false;
    this.logout.emit();
  }

  // Close the dropdown when clicking outside of it
  @HostListener('document:mousedown', ['$event'])
  onDocumentClick(event: MouseEvent) {
    if (this.isDropdownOpen && !this.elementRef.nativeElement.contains(event.target)) {
      this.isDropdownOpen = false;
    }
  }
}
